<?php
namespace App\\Services;use App\\Repositories\\ReminderRepository;use Illuminate\\Support\\Facades\\DB;use Illuminate\\Support\\Facades\\Http;
class ReminderDispatchService{
 public function __construct(private ReminderRepository $repo){}
 public function run():array{$processed=0;foreach($this->repo->dueIds() as $id){$this->dispatchOne($id);$processed++;}return ['processed'=>$processed];}
 private function dispatchOne(string $id):void{DB::transaction(function()use($id){$r=$this->repo->locked($id);if(!$r||$r->status!=='pending'||$r->scheduled_for->isFuture()||($r->next_attempt_at&&$r->next_attempt_at->isFuture()))return;$a=$r->appointment;$p=$a->patient;$c=$a->clinic;if($a->status==='cancelled'||$a->starts_at->isPast()){$r->status='skipped';$r->skip_reason='too_late';$r->save();return;}if(!$p->phone){$r->status='skipped';$r->skip_reason='no_phone';$r->save();return;}if(!$p->accepts_reminders){$r->status='skipped';$r->skip_reason='opted_out';$r->save();return;}$local=$a->starts_at->setTimezone($c->timezone);$message=sprintf('Hola %s, te recordamos tu cita en %s el %s a las %s. Responde SI para confirmar o NO para cancelar.',$p->name,$c->name,$local->format('d/m/Y'),$local->format('H:i'));$r->attempts++;$r->delivered_to=$p->phone;$r->next_attempt_at=null;try{$resp=Http::timeout(5)->withHeaders(['Idempotency-Key'=>$r->idempotency_key])->post(rtrim(env('PROVIDER_URL','http://provider:4010'),'/').'/messages',['to'=>$p->phone,'text'=>$message]);$code=$resp->status();if($code===202||($code===200&&$resp->json('duplicate')===true)){$r->status='sent';$r->sent_at=now();}elseif($code===422){$r->status='failed';}elseif($code===503||$code===504){$this->retryOrFail($r);}else{$r->status='failed';}}catch(\\Throwable $e){$this->retryOrFail($r);}$r->save();});}
 private function retryOrFail($r):void{if($r->attempts>=3){$r->status='failed';return;}$r->status='pending';$r->next_attempt_at=now()->addMinutes($r->attempts===1?1:5);}
}